using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability using the Bing Web Search API.
/// Set the "BING_API_KEY" environment variable with a valid Bing Search v7 key.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _http;
    private readonly string _apiKey;
    private const string Endpoint = "https://api.bing.microsoft.com/v7.0/search";

    public WebSearchTool(HttpClient http)
    {
        _http = http;
        _apiKey = Environment.GetEnvironmentVariable("BING_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the BING_API_KEY environment variable with a valid Bing Search v7 API key.");
    }

    [Description("Searches the web for the given query and returns a list of results with title, URL, and snippet.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"{Endpoint}?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("Ocp-Apim-Subscription-Key", _apiKey);

        using var response = await _http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());

        var results = new List<object>();
        if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray())
            {
                results.Add(new
                {
                    title = item.GetProperty("name").GetString(),
                    url = item.GetProperty("url").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found for the query.";
    }

    /// <summary>Returns the tool as an <see cref="AIFunction"/> for agent registration.</summary>
    public AIFunction AsAIFunction() =>
        AIFunctionFactory.Create(SearchWebAsync, name: "search_web", target: this);
}

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides in-memory note-taking capability so the agent can record and
/// retrieve findings during a research session.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    private sealed record Note(string Topic, string Content, DateTime CreatedAt);

    [Description("Saves a research note under the specified topic.")]
    public string SaveNote(
        [Description("The topic or category for this note")] string topic,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(new Note(topic, content, DateTime.UtcNow));
        return $"Note saved under topic '{topic}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieves all notes, optionally filtered by topic.")]
    public string GetNotes(
        [Description("Optional topic to filter notes by. Leave empty for all notes.")] string? topic = null)
    {
        var filtered = string.IsNullOrWhiteSpace(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
            return topic is null
                ? "No notes have been saved yet."
                : $"No notes found for topic '{topic}'.";

        var output = filtered.Select(n => new
        {
            topic = n.Topic,
            content = n.Content,
            created = n.CreatedAt.ToString("u"),
        });

        return JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns the tools as <see cref="AIFunction"/> instances for agent registration.</summary>
    public IEnumerable<AIFunction> AsAIFunctions() =>
    [
        AIFunctionFactory.Create(SaveNote, name: "save_note", target: this),
        AIFunctionFactory.Create(GetNotes, name: "get_notes", target: this),
    ];
}

