using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// ── Configuration ───────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ── Dependency injection ────────────────────────────────────────────────────
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient();

services.AddChatClient(builder =>
    builder.Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

var sp = services.BuildServiceProvider();

// ── Tools ───────────────────────────────────────────────────────────────────
var httpFactory = sp.GetRequiredService<IHttpClientFactory>();
var webSearch = new WebSearchTool(httpFactory.CreateClient());
var notes = new NoteTakingTool();

var tools = new List<AITool>();
tools.Add(webSearch.AsAIFunction());
tools.AddRange(notes.AsAIFunctions());

// ── Agent setup ─────────────────────────────────────────────────────────────
var chatClient = sp.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Your job is to thoroughly research a topic
        the user provides by performing multiple web searches, saving important
        findings as notes, and then producing a well-organized summary.

        Follow this workflow:
        1. Break the topic into 2-4 sub-questions worth investigating.
        2. For each sub-question, use the search_web tool to find relevant information.
        3. Use the save_note tool to record key facts, statistics, and source URLs
           under descriptive topic names.
        4. After finishing your research, use get_notes to review everything you collected.
        5. Present a final summary with sections, key findings, and source citations.

        Always cite your sources with URLs. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

// ── Interactive loop ────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent Ready          ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input))
        continue;
    if (input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and take notes)");
    Console.ResetColor();

    try
    {
        var session = await agent.CreateSessionAsync();

        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 4096,
            },
        };

        var response = await agent.RunAsync(input, session, runOptions);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();

        foreach (var message in response.Messages)
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.WriteLine(message.Text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

