/// Set the "BING_API_KEY" environment variable with a valid Bing Search v7 key.
/// </summary>
public sealed class WebSearchTool(HttpClient http)
{
    private readonly string _apiKey = Environment.GetEnvironmentVariable("BING_API_KEY")
        ?? throw new InvalidOperationException(
            "Set the BING_API_KEY environment variable with a valid Bing Search v7 API key.");

    private const string Endpoint = "https://api.bing.microsoft.com/v7.0/search";

    [Description("Searches the web for the given query and returns a list of results with title, URL, and snippet.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"{Endpoint}?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("Ocp-Apim-Subscription-Key", _apiKey);

        using var response = await http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());

        var results = new List<object>();
        if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray())
            {
                results.Add(new
                {
                    title = item.GetProperty("name").GetString(),
                    url = item.GetProperty("url").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found for the query.";
    }

    /// <summary>Returns the tool as an <see cref="AIFunction"/> for agent registration.</summary>
    public AIFunction AsAIFunction() =>
        AIFunctionFactory.Create(SearchWebAsync, name: "search_web");
}

