namespace ResearchAgent.Tools;

/// <summary>
/// Provides in-memory note-taking capability so the agent can record and
/// retrieve findings during a research session.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    private sealed record Note(string Topic, string Content, DateTime CreatedAt);

    [Description("Saves a research note under the specified topic.")]
    public string SaveNote(
        [Description("The topic or category for this note")] string topic,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(new Note(topic, content, DateTime.UtcNow));
        return $"Note saved under topic '{topic}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieves all notes, optionally filtered by topic.")]
    public string GetNotes(
        [Description("Optional topic to filter notes by. Leave empty for all notes.")] string? topic = null)
    {
        var filtered = string.IsNullOrWhiteSpace(topic)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
            return topic is null
                ? "No notes have been saved yet."
                : $"No notes found for topic '{topic}'.";

        var output = filtered.Select(n => new
        {
            topic = n.Topic,
            content = n.Content,
            created = n.CreatedAt.ToString("u"),
        });

        return JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>Returns the tools as <see cref="AIFunction"/> instances for agent registration.</summary>
    public IEnumerable<AIFunction> AsAIFunctions() =>
    [
        AIFunctionFactory.Create(SaveNote, name: "save_note"),
        AIFunctionFactory.Create(GetNotes, name: "get_notes"),
    ];
}

